{'id': 'effects', 'title': 'Effects and keying'}
{"id": "chroma-key", "name": "Chroma Key", "summary": "Remove a background colour, such as a green screen, so what is on the tracks behind shows through.", "page": "effects/chroma-key", "anchor": "key-out-a-color", "where": "Inspector ▸ Clip ▸ Picture ▸ Chroma Key ▸ Key out a color"}
{"id": "chroma-key-color", "name": "Key Color", "summary": "Choose the colour to remove.", "page": "effects/chroma-key", "anchor": "key-color", "where": "Inspector ▸ Clip ▸ Picture ▸ Chroma Key ▸ Key Color"}
{"id": "chroma-key-pick-from-canvas", "name": "Pick from Canvas", "summary": "Click the preview to sample the key colour; picking also turns the key on.", "page": "effects/chroma-key", "anchor": "pick-from-canvas", "where": "Inspector ▸ Clip ▸ Picture ▸ Chroma Key ▸ Pick from Canvas", "keys": "⎋"}
{"id": "chroma-key-tolerance", "name": "Tolerance", "summary": "Set how far from the key colour still counts as background.", "page": "effects/chroma-key", "anchor": "tolerance", "where": "Inspector ▸ Clip ▸ Picture ▸ Chroma Key ▸ Tolerance"}
{"id": "chroma-key-softness", "name": "Softness", "summary": "Set how gradual the edge of the key is.", "page": "effects/chroma-key", "anchor": "softness", "where": "Inspector ▸ Clip ▸ Picture ▸ Chroma Key ▸ Softness"}
{"id": "chroma-key-spill", "name": "Spill", "summary": "Set how much of the key colour's spill is removed from the edges that remain.", "page": "effects/chroma-key", "anchor": "spill", "where": "Inspector ▸ Clip ▸ Picture ▸ Chroma Key ▸ Spill"}
{"id": "remove-background", "name": "Remove Background", "summary": "Keep the person in a video or picture and make the rest transparent, with no green screen, upload or key.", "page": "effects/remove-background", "anchor": "turn-it-on", "where": "Clip ▸ Remove Background"}
{"id": "remove-background-subject", "name": "Subject", "summary": "For pictures, choose whether to keep the person or the foreground subject, whatever it is.", "page": "effects/remove-background", "anchor": "subject", "where": "Inspector ▸ Clip ▸ Picture ▸ Background ▸ Subject: Person, Foreground"}
{"id": "remove-background-keep", "name": "Background: Remove or Keep", "summary": "Choose whether to draw the subject alone or the whole clip, keeping the masks either way.", "page": "effects/remove-background", "anchor": "background", "where": "Inspector ▸ Clip ▸ Picture ▸ Background ▸ Background: Remove, Keep"}
{"id": "remove-background-edge", "name": "Edge", "summary": "Pull the cut-out outline in or push it out.", "page": "effects/remove-background", "anchor": "edge", "where": "Inspector ▸ Clip ▸ Picture ▸ Background ▸ Edge"}
{"id": "remove-background-feather", "name": "Feather", "summary": "Set how soft the cut-out outline is.", "page": "effects/remove-background", "anchor": "feather", "where": "Inspector ▸ Clip ▸ Picture ▸ Background ▸ Feather"}
{"id": "remove-background-rows-dimmed", "name": "Rows dimmed until it is on", "summary": "Subject, Background, Edge and Feather stay dimmed until every selected clip has Remove Background on.", "page": "effects/remove-background", "anchor": "turn-it-on", "where": "Inspector ▸ Clip ▸ Picture ▸ Background"}
{"id": "remove-background-status", "name": "Status", "summary": "A read-out says where the clip's masks stand, and why a clip draws whole.", "page": "effects/remove-background", "anchor": "status", "where": "Inspector ▸ Clip ▸ Picture ▸ Background ▸ Status"}
{"id": "remove-background-analyze-now", "name": "Analyze Now", "summary": "Make the clip's masks now, or try again after a failure.", "page": "effects/remove-background", "anchor": "analyze-now", "where": "Inspector ▸ Clip ▸ Picture ▸ Background ▸ Analyze Now"}
{"id": "remove-background-masks", "name": "Automatic, cached masks", "summary": "You never start the analysis yourself: the masks are made as soon as Remove Background is on, for the frames the clip plays, and kept in the project's cache.", "page": "effects/remove-background", "anchor": "how-the-masks-are-made", "where": "Automatic"}
{"id": "remove-background-draws-whole-until-ready", "name": "Whole until its masks exist", "summary": "A clip with Remove Background on shows uncut until each frame has its mask, and updates by itself as the masks land.", "page": "effects/remove-background", "anchor": "how-the-masks-are-made", "where": "Preview"}
{"id": "remove-background-pictures", "name": "Remove Background on pictures", "summary": "A picture's mask is made once on this Mac, from the picture as the preview draws it.", "page": "effects/remove-background", "anchor": "pictures", "where": "Inspector ▸ Clip ▸ Picture ▸ Background ▸ Subject"}
{"id": "remove-background-export-waits", "name": "Exports wait for the masks", "summary": "An export draws the subject alone in every frame and waits until every mask it draws is made.", "page": "effects/remove-background", "anchor": "exports", "where": "File ▸ Export… (Preparing…)"}
{"id": "remove-background-render-frame-waits", "name": "render_frame waits for the masks", "summary": "A single rendered frame waits up to 30 seconds for the masks it needs, then draws the clip whole and says so.", "page": "effects/remove-background", "anchor": "exports", "where": "File ▸ Save Frame…", "keys": "⌥⌘E"}
{"id": "text-behind-subject", "name": "Text Behind Subject", "summary": "Put a new title behind the person in a camera clip or photo in one step at the playhead.", "page": "effects/text-behind-subject", "anchor": "text-behind-subject-in-one-step", "where": "Insert ▸ Text Behind Subject"}
{"id": "behind-subject-section", "name": "Behind Subject section", "summary": "Put any clip that draws behind a subject by hand with one checkbox.", "page": "effects/text-behind-subject", "anchor": "behind-subject-by-hand", "where": "Inspector ▸ Clip ▸ Picture ▸ Behind Subject ▸ Behind subject"}
{"id": "behind-subject-what-cuts-it", "name": "What cuts a clip behind the subject", "summary": "A clip with Behind subject on is cut, at every moment, by the person in every cut-out clip on a track behind it.", "page": "effects/text-behind-subject", "anchor": "what-cuts-the-clip", "where": "Automatic"}
{"id": "behind-subject-no-cutout-note", "name": "No cut-out behind note", "summary": "With one clip selected and the box on, a note says when nothing cuts it at the playhead.", "page": "effects/text-behind-subject", "anchor": "behind-subject-by-hand", "where": "Inspector ▸ Clip ▸ Picture ▸ Behind Subject"}
{"id": "drop-shadow", "name": "Drop Shadow", "summary": "Add a drop shadow cast by the layer's own shape: the picture, a text clip's letters, or a shape's outline and fill.", "page": "effects/shadow", "anchor": "drop-shadow", "where": "Inspector ▸ Clip ▸ Picture ▸ Shadow ▸ Drop shadow"}
{"id": "shadow-color", "name": "Shadow Color", "summary": "Set the shadow's colour.", "page": "effects/shadow", "anchor": "color", "where": "Inspector ▸ Clip ▸ Picture ▸ Shadow ▸ Color"}
{"id": "shadow-opacity", "name": "Shadow Opacity", "summary": "Set the shadow's strength.", "page": "effects/shadow", "anchor": "opacity", "where": "Inspector ▸ Clip ▸ Picture ▸ Shadow ▸ Opacity"}
{"id": "shadow-blur", "name": "Shadow Blur", "summary": "Soften the shadow.", "page": "effects/shadow", "anchor": "blur", "where": "Inspector ▸ Clip ▸ Picture ▸ Shadow ▸ Blur"}
{"id": "shadow-angle", "name": "Shadow Angle", "summary": "Set which way the shadow falls.", "page": "effects/shadow", "anchor": "angle", "where": "Inspector ▸ Clip ▸ Picture ▸ Shadow ▸ Angle"}
{"id": "shadow-distance", "name": "Shadow Distance", "summary": "Set how far the shadow falls.", "page": "effects/shadow", "anchor": "distance", "where": "Inspector ▸ Clip ▸ Picture ▸ Shadow ▸ Distance"}
{"id": "filter-stack", "name": "Filter stack", "summary": "A clip can carry up to four filters.", "page": "effects/filters", "anchor": "stack-and-reorder-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters"}
{"id": "add-filter", "name": "Add Filter", "summary": "Append a new filter to the end of the stack.", "page": "effects/filters", "anchor": "add-a-filter", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ Add Filter"}
{"id": "filter-order", "name": "Filter order", "summary": "Move a filter by picking a different number in its row's place popup.", "page": "effects/filters", "anchor": "stack-and-reorder-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ place popup"}
{"id": "filter-kind", "name": "Filter kind", "summary": "Change what a filter does, keeping its amount.", "page": "effects/filters", "anchor": "the-seven-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ kind popup"}
{"id": "filter-amount", "name": "Filter Amount", "summary": "Set a filter's strength.", "page": "effects/filters", "anchor": "set-how-strong-a-filter-is", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ Amount"}
{"id": "remove-filter", "name": "Remove Filter", "summary": "Take a filter off the clip.", "page": "effects/filters", "anchor": "remove-a-filter", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ Remove"}
{"id": "filter-blur", "name": "Blur filter", "summary": "Soften the picture.", "page": "effects/filters", "anchor": "the-seven-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ kind popup ▸ Blur"}
{"id": "filter-sharpen", "name": "Sharpen filter", "summary": "Crisp up the picture.", "page": "effects/filters", "anchor": "the-seven-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ kind popup ▸ Sharpen"}
{"id": "filter-pixelate", "name": "Pixelate filter", "summary": "Break the picture into blocks.", "page": "effects/filters", "anchor": "the-seven-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ kind popup ▸ Pixelate"}
{"id": "filter-sepia", "name": "Sepia filter", "summary": "Give the picture a warm old-photo tone.", "page": "effects/filters", "anchor": "the-seven-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ kind popup ▸ Sepia"}
{"id": "filter-noir", "name": "Noir filter", "summary": "Turn the picture black and white, with added contrast.", "page": "effects/filters", "anchor": "the-seven-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ kind popup ▸ Noir"}
{"id": "filter-vignette", "name": "Vignette filter", "summary": "Darken the edges and corners.", "page": "effects/filters", "anchor": "the-seven-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ kind popup ▸ Vignette"}
{"id": "filter-invert", "name": "Invert filter", "summary": "Invert the picture's colours.", "page": "effects/filters", "anchor": "the-seven-filters", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters ▸ kind popup ▸ Invert"}
{"id": "filters-on-adjustment-clips", "name": "Filters on adjustment clips", "summary": "Sepia, Noir, Vignette and Invert given to an adjustment clip also apply to the picture behind it.", "page": "effects/filters", "anchor": "filters-on-an-adjustment-clip", "where": "Edit ▸ Paste Attributes", "keys": "⌥⌘V"}
{"id": "filters-in-an-action", "name": "Filters in an action", "summary": "A filter's amount can animate, while adding or removing a filter is never animated.", "page": "effects/filters", "anchor": "animate-a-filter", "where": "Inspector ▸ Clip ▸ Picture ▸ Filters with an action selected"}
{"id": "reflection", "name": "Reflection", "summary": "Hang a mirrored copy of the layer under it, fading out.", "page": "effects/reflection", "anchor": "add-a-reflection", "where": "Inspector ▸ Clip ▸ Picture ▸ Reflection ▸ Mirror the layer below itself"}
{"id": "reflection-opacity", "name": "Reflection Opacity", "summary": "Set how strong the reflection is where it touches the layer.", "page": "effects/reflection", "anchor": "shape-the-reflection", "where": "Inspector ▸ Clip ▸ Picture ▸ Reflection ▸ Opacity"}
{"id": "reflection-height", "name": "Reflection Height", "summary": "Set how much of the layer is mirrored.", "page": "effects/reflection", "anchor": "shape-the-reflection", "where": "Inspector ▸ Clip ▸ Picture ▸ Reflection ▸ Height"}
{"id": "reflection-gap", "name": "Reflection Gap", "summary": "Set the space between the layer and its reflection.", "page": "effects/reflection", "anchor": "shape-the-reflection", "where": "Inspector ▸ Clip ▸ Picture ▸ Reflection ▸ Gap"}
{"id": "reflection-falloff", "name": "Reflection Falloff", "summary": "Set how the reflection fades away.", "page": "effects/reflection", "anchor": "shape-the-reflection", "where": "Inspector ▸ Clip ▸ Picture ▸ Reflection ▸ Falloff"}
{"id": "spotlight", "name": "Spotlight", "summary": "Dim the clip outside a rectangle or ellipse, and optionally magnify what is inside.", "page": "effects/spotlight", "anchor": "spotlight-a-region", "where": "Inspector ▸ Clip ▸ Picture ▸ Spotlight ▸ Spotlight a region"}
{"id": "spotlight-shape", "name": "Spotlight Shape", "summary": "Choose a rectangle or an ellipse.", "page": "effects/spotlight", "anchor": "the-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Spotlight ▸ Shape: Rectangle, Ellipse"}
{"id": "spotlight-center", "name": "Spotlight Center", "summary": "Place the spotlight on the clip's picture.", "page": "effects/spotlight", "anchor": "place-the-spotlight", "where": "Inspector ▸ Clip ▸ Picture ▸ Spotlight ▸ Center X, Center Y"}
{"id": "spotlight-size", "name": "Spotlight Size", "summary": "Set the spotlight's width and height.", "page": "effects/spotlight", "anchor": "place-the-spotlight", "where": "Inspector ▸ Clip ▸ Picture ▸ Spotlight ▸ Width, Height"}
{"id": "spotlight-feather", "name": "Spotlight Feather", "summary": "Soften the spotlight's edge.", "page": "effects/spotlight", "anchor": "the-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Spotlight ▸ Feather"}
{"id": "spotlight-dim", "name": "Spotlight Dim", "summary": "Set how much darker everything outside the region is.", "page": "effects/spotlight", "anchor": "what-gets-dimmed", "where": "Inspector ▸ Clip ▸ Picture ▸ Spotlight ▸ Dim"}
{"id": "spotlight-zoom", "name": "Spotlight Zoom", "summary": "Magnify what is inside the spotlight.", "page": "effects/spotlight", "anchor": "magnify-the-region", "where": "Inspector ▸ Clip ▸ Picture ▸ Spotlight ▸ Zoom"}
{"id": "obscure-regions", "name": "Obscure regions", "summary": "Hide a face, password field or phone number behind up to four blurred or pixelated regions per clip.", "page": "effects/obscure", "anchor": "", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure"}
{"id": "obscure-add-region", "name": "Add Region", "summary": "Add a 480 × 270 pixelated box at the centre of the layer.", "page": "effects/obscure", "anchor": "add-a-region-without-drawing", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure ▸ Add Region"}
{"id": "obscure-place-on-canvas", "name": "Place on Canvas", "summary": "Drag a rectangle over the selected clip to add a region there.", "page": "effects/obscure", "anchor": "draw-a-region-on-the-picture", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure ▸ Place on Canvas", "keys": "⎋"}
{"id": "obscure-region-kind", "name": "Region kind", "summary": "Choose Pixelate, which hides, or Blur, which softens.", "page": "effects/obscure", "anchor": "choose-pixelate-or-blur", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure ▸ Region N ▸ kind popup"}
{"id": "obscure-region-shape", "name": "Region shape", "summary": "Choose a rectangle or an ellipse for a region.", "page": "effects/obscure", "anchor": "the-region-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure ▸ Region N ▸ Shape: Rectangle, Ellipse"}
{"id": "obscure-region-amount", "name": "Region Amount", "summary": "Set how strongly the region hides.", "page": "effects/obscure", "anchor": "the-region-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure ▸ Region N ▸ Amount"}
{"id": "obscure-region-feather", "name": "Region Feather", "summary": "Ramp the effect in over the region's edge.", "page": "effects/obscure", "anchor": "the-region-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure ▸ Region N ▸ Feather"}
{"id": "obscure-region-center", "name": "Region Center", "summary": "Place a region as numbers, in source pixels from the layer's centre.", "page": "effects/obscure", "anchor": "the-region-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure ▸ Region N ▸ Center"}
{"id": "obscure-region-size", "name": "Region Size", "summary": "Set a region's width and height as numbers.", "page": "effects/obscure", "anchor": "the-region-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure ▸ Region N ▸ Size"}
{"id": "obscure-remove-region", "name": "Remove Region", "summary": "Take a region off the clip.", "page": "effects/obscure", "anchor": "remove-a-region", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure ▸ Region N ▸ Remove"}
{"id": "obscure-canvas-grips", "name": "Region grips on the canvas", "summary": "Move a selected clip's regions and resize them directly on the preview.", "page": "effects/obscure", "anchor": "move-and-resize-a-region-on-the-canvas", "where": "Drag a region's centre cross to move it", "keys": "⌥"}
{"id": "obscure-animate", "name": "Animating a region", "summary": "Each region's numbers can be animated like any other property.", "page": "effects/obscure", "anchor": "animate-a-region", "where": "Inspector ▸ Clip ▸ Picture ▸ Obscure with an action selected"}
{"id": "hide-while-silent", "name": "Hide While Silent", "summary": "Fade a clip out in the pauses of a chosen file's speech and back in as it resumes.", "page": "effects/hide-while-silent", "anchor": "turn-it-on", "where": "Inspector ▸ Clip ▸ Picture ▸ Hide While Silent ▸ Hide while silent"}
{"id": "hide-while-silent-speech-from", "name": "Speech from", "summary": "Pick which file's speech the clip follows.", "page": "effects/hide-while-silent", "anchor": "choose-which-file-to-follow", "where": "Inspector ▸ Clip ▸ Picture ▸ Hide While Silent ▸ Speech from"}
{"id": "hide-while-silent-pre-roll", "name": "Pre-roll", "summary": "Set how long before each run of words the clip is fully back.", "page": "effects/hide-while-silent", "anchor": "adjust-the-timing", "where": "Inspector ▸ Clip ▸ Picture ▸ Hide While Silent ▸ Pre-roll"}
{"id": "hide-while-silent-hold", "name": "Hold", "summary": "Set how long the clip stays after each run of words.", "page": "effects/hide-while-silent", "anchor": "adjust-the-timing", "where": "Inspector ▸ Clip ▸ Picture ▸ Hide While Silent ▸ Hold"}
{"id": "hide-while-silent-fade", "name": "Fade", "summary": "Set how long the clip takes to fade out and in.", "page": "effects/hide-while-silent", "anchor": "adjust-the-timing", "where": "Inspector ▸ Clip ▸ Picture ▸ Hide While Silent ▸ Fade"}
{"id": "hide-while-silent-coverage", "name": "Where the file does not play", "summary": "Where the followed file does not play at all, the clip shows.", "page": "effects/hide-while-silent", "anchor": "when-the-followed-file-stops-playing"}
{"id": "hide-while-silent-stays-out-of-opacity", "name": "It stays out of Opacity", "summary": "The fade is only in the drawn picture, so the clip's own Opacity is untouched.", "page": "effects/hide-while-silent", "anchor": "the-fade-stays-out-of-opacity"}
{"id": "hide-while-silent-timeline-line", "name": "The line on the timeline", "summary": "The timeline draws a teal line over a gated clip's picture: at the top the clip shows, at the bottom it is hidden.", "page": "effects/hide-while-silent", "anchor": "see-it-on-the-timeline", "where": "Timeline clip"}
